import { createServer } from "node:http";
import { createHash } from "node:crypto";

const html = '<!doctype html><script type="module" src="/assets/index-4f9a1c2e.js"></script>';
const etag = '"' + createHash("sha1").update(html).digest("hex").slice(0, 16) + '"';

createServer((req, res) => {
  if (req.url.startsWith("/assets/")) {
    // hashed file: the URL itself is the version
    res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
    res.setHeader("Content-Type", "text/javascript");
    return res.end("console.log('app v2')");
  }
  // HTML entry point: may be stored, but check with the server before every use
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("ETag", etag);
  if (req.headers["if-none-match"] === etag) {
    res.statusCode = 304; // Not Modified: headers only, no body
    return res.end();
  }
  res.setHeader("Content-Type", "text/html");
  res.end(html);
}).listen(3000);

// old HTML asks for a chunk the new deploy removed from the server
window.addEventListener("vite:preloadError", (event) => {
  event.preventDefault(); // don't throw the import error
  window.location.reload(); // a reload fetches the new HTML (it is no-cache)
});
